            finalAnswer = finalAnswer * invFactorials[n - r] % MOD;
        }
        pw.println(finalAnswer);
        pw.close();
    }

    private long power(long base, int exp, long mod) {
        long res = 1;
        long cur = base % mod;
        for (int i = 0; i < exp; i++) {
            res = (res * cur) % mod;
        }
        return res;
    }

    private long computeInverse(long a, long m) {
        return power(a, (int) m - 2, m);
    }
