    vector<long long> factorials(n + 1, 1);
    vector<long long> invFactorials(n + 1, 1);

    auto power = [&](long long base, int exp) -> long long {
        long long res = 1;
        long long cur = base % MOD;
        for (int i = 0; i < exp; i++) {
            res = (res * cur) % MOD;
        }
        return res;
    };

    auto computeInverse = [&](long long a) -> long long {
